const setupCheckOutlets = `-- name: SetupCheckOutlets :many
SELECT o.id AS outlet_id, o.code AS outlet_code,
       (SELECT count(*) FROM pos_price_list_items i JOIN pos_products p ON p.property_id = i.property_id AND p.id = i.product_id AND p.is_active
         WHERE i.property_id = o.property_id AND i.price_list_id = o.price_list_id AND i.is_sold) AS sold_products,
       (SELECT count(*) FROM pos_tables t JOIN pos_areas a ON a.property_id = t.property_id AND a.id = t.area_id
         WHERE a.property_id = o.property_id AND a.outlet_id = o.id AND t.is_active) AS tables, o.uses_tables, (o.drawer IS NULL)::boolean AS no_drawer, (o.receipt_printer_id IS NULL)::boolean AS no_printer
FROM pos_outlets o WHERE o.tenant_id = $1 AND o.property_id = $2 AND o.is_active
ORDER BY o.code
`

type SetupCheckOutletsParams struct {
	TenantID   int64
	PropertyID int64
}

type SetupCheckOutletsRow struct {
	OutletID     int64
	OutletCode   string
	SoldProducts int64
	Tables       int64
	UsesTables   bool
	NoDrawer     bool
	NoPrinter    bool
}

// Active outlets with nothing to sell, and outlets that use tables and have none.
func (q *Queries) SetupCheckOutlets(ctx context.Context, arg SetupCheckOutletsParams) ([]SetupCheckOutletsRow, error) {
	rows, err := q.db.Query(ctx, setupCheckOutlets, arg.TenantID, arg.PropertyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SetupCheckOutletsRow{}
	for rows.Next() {
		var i SetupCheckOutletsRow
		if err := rows.Scan(
			&i.OutletID,
			&i.OutletCode,
			&i.SoldProducts,
			&i.Tables,
			&i.UsesTables,
			&i.NoDrawer,
			&i.NoPrinter,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setupCheckStations = `-- name: SetupCheckStations :many
SELECT o.id AS outlet_id, o.code AS outlet_code, p.id AS product_id, p.code AS product_code, s.id AS station_id, s.code AS station_code
FROM pos_outlets o
JOIN pos_price_list_items i ON i.property_id = o.property_id AND i.price_list_id = o.price_list_id AND i.is_sold
JOIN pos_products p ON p.property_id = i.property_id AND p.id = i.product_id AND p.is_active
LEFT JOIN pos_stations s ON s.property_id = p.property_id AND s.id = COALESCE(i.station_id, p.station_id)
WHERE o.tenant_id = $1 AND o.property_id = $2 AND o.is_active AND o.order_mode IN ('PRINT', 'KDS')
  AND (s.id IS NULL OR NOT s.is_active OR (o.order_mode = 'PRINT' AND s.printer_id IS NULL) OR (o.order_mode = 'KDS' AND NOT s.kds_enabled))
ORDER BY o.code, p.code
`

type SetupCheckStationsParams struct {
	TenantID   int64
	PropertyID int64
}

type SetupCheckStationsRow struct {
	OutletID    int64
	OutletCode  string
	ProductID   int64
	ProductCode string
	StationID   *int64
	StationCode *string
}

// ---------------------------------------------------------------- the check of the setup
// Outlets whose order mode needs a station with a printer or a screen, and whose products have none.
func (q *Queries) SetupCheckStations(ctx context.Context, arg SetupCheckStationsParams) ([]SetupCheckStationsRow, error) {
	rows, err := q.db.Query(ctx, setupCheckStations, arg.TenantID, arg.PropertyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SetupCheckStationsRow{}
	for rows.Next() {
		var i SetupCheckStationsRow
		if err := rows.Scan(
			&i.OutletID,
			&i.OutletCode,
			&i.ProductID,
			&i.ProductCode,
			&i.StationID,
			&i.StationCode,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

